<?php ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Primonizer Forex AI — Multi-Timeframe Visual Tutor</title><style>
:root{--bg:#050b13;--p:#0b1522;--line:#20364d;--txt:#edf6ff;--muted:#91a7bd;--g:#28e0a1;--r:#ff5f73;--y:#ffd166;--b:#55a9ff}*{box-sizing:border-box}body{margin:0;background:#050b13;color:var(--txt);font-family:Segoe UI,Arial,sans-serif}.wrap{max-width:1300px;margin:auto;padding:18px}.nav{display:flex;justify-content:space-between;gap:15px;align-items:center;margin-bottom:18px}.brand{font-weight:900;font-size:21px}.brand span{color:var(--g)}.status,.tag{border:1px solid #31516e;border-radius:999px;padding:7px 10px;font-size:11px;color:#b8d1e8}.hero,.grid{display:grid;grid-template-columns:1.1fr .9fr;gap:16px}.card,.panel{background:linear-gradient(180deg,#0e1c2d,#08121e);border:1px solid var(--line);border-radius:17px;padding:18px}.hero h1{font-size:clamp(30px,5vw,54px);line-height:1.02;margin:10px 0}.muted,.small{color:var(--muted);line-height:1.55}.eyebrow{font-size:11px;font-weight:900;letter-spacing:.15em;color:var(--g);text-transform:uppercase}.controls{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:16px}label{font-size:11px;color:var(--muted);display:block;margin-bottom:5px}select,input{width:100%;background:#06101b;border:1px solid var(--line);color:var(--txt);padding:11px;border-radius:10px}.uploadGrid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin-top:12px}.slot{border:1px dashed #39617f;border-radius:13px;padding:12px;background:#07121e}.slot b{font-size:12px}.thumb{display:none;width:100%;height:150px;object-fit:contain;margin-top:8px;border-radius:8px;background:#02070d;cursor:zoom-in}.btn{width:100%;border:0;border-radius:11px;padding:14px;margin-top:14px;background:var(--g);color:#03120e;font-weight:900;cursor:pointer}.btn:disabled{opacity:.5}.checks{display:grid;gap:10px;margin-top:15px}.check{font-size:13px;color:#bfd0e0}.dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--g);margin-right:8px}.result{display:none;margin-top:18px}.overall{display:flex;justify-content:space-between;align-items:center;gap:15px;flex-wrap:wrap}.direction{font-size:22px;font-weight:900;padding:10px 14px;border-radius:12px}.bull{color:var(--g);background:#06251c}.bear{color:var(--r);background:#2a0a12}.neutral{color:var(--y);background:#2a2106}.charts{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin-top:15px}.chartCard{border:1px solid var(--line);border-radius:14px;overflow:hidden;background:#02070d}.chartHead{padding:11px;background:#091521;display:flex;justify-content:space-between;gap:8px}.chartCard img{display:block;width:100%;max-height:480px;object-fit:contain;cursor:zoom-in}.chartInfo{padding:12px}.ob{border-left:4px solid var(--g);padding:10px;background:#061a14}.entry{border-left:4px solid var(--y);padding:10px;background:#1d1805;margin-top:8px}.grid3{display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px;margin-top:14px}.panel h3{margin:0 0 10px}.story li{margin:7px 0;color:#cbd9e6}.step{padding:9px 0;border-bottom:1px solid #1b2d40}.step:last-child{border:0}.confluence{margin-top:14px}.final{font-size:18px;font-weight:800;white-space:pre-line;line-height:1.7}.modal{display:none;position:fixed;inset:0;background:#000d;z-index:50;align-items:center;justify-content:center;padding:20px}.modal.open{display:flex}.modal img{max-width:95vw;max-height:90vh;object-fit:contain;cursor:zoom-out}.close{position:fixed;right:20px;top:15px;font-size:30px;cursor:pointer}.error{color:var(--r);margin-top:10px}.footer{text-align:center;color:#6f8398;padding:25px;font-size:11px}@media(max-width:850px){.hero,.grid,.charts,.grid3{grid-template-columns:1fr}.uploadGrid{grid-template-columns:1fr}.controls{grid-template-columns:1fr}.wrap{padding:12px}}
</style></head><body><div class="wrap"><header class="nav"><div class="brand">PRIMONIZER <span>FOREX AI</span></div><div class="status">● 4-TIMEFRAME VISUAL TUTOR</div></header><section class="hero"><div class="card"><div class="eyebrow">Top-down chart intelligence</div><h1>Upload 1–4 timeframes. See the whole market story.</h1><p class="muted">Upload H4/H1/M15/M5 or any combination. Each chart is analyzed independently, then the engine combines the higher-timeframe structure with lower-timeframe entry refinement.</p><form id="form"><div class="controls"><div><label>SYMBOL</label><select name="symbol"><option>XAUUSD</option><option>EURUSD</option><option>GBPUSD</option><option>USDJPY</option><option>BTCUSD</option><option>V75</option><option>OTHER</option></select></div></div><div class="uploadGrid" id="uploads"></div><button class="btn" id="go">ANALYZE ALL TIMEFRAMES</button><div id="err" class="error"></div></form></div><div class="card"><div class="eyebrow">What happens</div><div class="checks"><div class="check"><span class="dot"></span>Full visible chart is read, not only the newest candles.</div><div class="check"><span class="dot"></span>Every timeframe gets its own marked entry, invalidation and target.</div><div class="check"><span class="dot"></span>Valid Order Block candidates are marked and the reason is explained.</div><div class="check"><span class="dot"></span>Charts are clickable for full-size preview and zoom.</div><div class="check"><span class="dot"></span>Higher timeframe = context; lower timeframe = refinement.</div><div class="check"><span class="dot"></span>Final conclusion combines all uploaded charts instead of trusting one timeframe.</div></div><p class="small">Directional output is a conditional scenario based on visible evidence, not a guaranteed next-candle prediction.</p></div></section><section id="result" class="result"><div class="card"><div class="overall"><div><span class="tag" id="count"></span> <span class="tag">MULTI-TF CONFLUENCE</span></div><div id="dir" class="direction neutral">WAIT</div></div><h2 id="headline"></h2><p id="state" class="muted"></p></div><div id="charts" class="charts"></div><div class="grid3"><div class="panel"><h3>📖 Market story</h3><ol id="story" class="story"></ol></div><div class="panel"><h3>🎓 Tutorial</h3><div id="tutorial"></div></div><div class="panel"><h3>🎯 Final entry plan</h3><div id="plan"></div></div></div><div class="panel confluence"><h3>🔗 Four-chart confluence</h3><div id="conf"></div></div><div class="panel confluence"><h3>🧭 Directional diagram</h3><div id="final" class="final"></div><p class="small" id="risk"></p></div></section><div class="footer">Primonizer Forex AI • Visual research and trader education</div></div><div id="modal" class="modal"><span class="close" id="close">×</span><img id="big" alt="Chart zoom"></div><script>
const upload=document.getElementById('uploads'),modal=document.getElementById('modal'),big=document.getElementById('big');let files=[];for(let i=0;i<4;i++){const s=document.createElement('div');s.className='slot';s.innerHTML='<b>TIMEFRAME '+(i+1)+'</b><select class="tf"><option>H4</option><option>H1</option><option>M30</option><option>M15</option><option>M5</option><option>M1</option><option>D1</option><option>UNKNOWN</option></select><input class="file" type="file" accept="image/png,image/jpeg,image/webp"><img class="thumb">';upload.appendChild(s);const inp=s.querySelector('.file'),im=s.querySelector('.thumb');inp.addEventListener('change',()=>{if(inp.files[0]){im.src=URL.createObjectURL(inp.files[0]);im.style.display='block'}});im.onclick=()=>{big.src=im.src;modal.classList.add('open')}}
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}function color(t){if(['OB_BULL','SUPPORT','ENTRY','HL'].includes(t))return '#28e0a1';if(['OB_BEAR','RESISTANCE','INVALIDATION','LH'].includes(t))return '#ff5f73';if(t==='FVG')return '#55a9ff';if(['LIQUIDITY','SWEEP','TARGET','PREMIUM','DISCOUNT'].includes(t))return '#ffd166';return '#fff'}
function drawOverlay(src,a){const c=document.createElement('canvas'),im=new Image();im.src=src;return new Promise(r=>im.onload=()=>{const scale=Math.min(1,1200/im.naturalWidth),w=Math.round(im.naturalWidth*scale),h=Math.round(im.naturalHeight*scale);c.width=w;c.height=h;const x=c.getContext('2d');x.drawImage(im,0,0,w,h);x.font='700 '+Math.max(12,w/75)+'px Segoe UI';(a.annotations||[]).forEach(o=>{const X=(+o.x||0)*w,Y=(+o.y||0)*h,C=color(o.type);x.strokeStyle=C;x.fillStyle=C;x.lineWidth=Math.max(2,w/500);if(o.x2!=null&&o.y2!=null){const X2=(+o.x2||0)*w,Y2=(+o.y2||0)*h;x.globalAlpha=.18;x.fillRect(Math.min(X,X2),Math.min(Y,Y2),Math.abs(X2-X),Math.abs(Y2-Y));x.globalAlpha=1;x.strokeRect(Math.min(X,X2),Math.min(Y,Y2),Math.abs(X2-X),Math.abs(Y2-Y))}else{x.beginPath();x.arc(X,Y,Math.max(5,w/130),0,Math.PI*2);x.fill()}x.fillText(o.label||o.type,Math.min(w-150,Math.max(3,X+7)),Math.max(15,Y-7))});const p=a.path||[];if(p.length>1){x.strokeStyle=a.direction==='BEARISH'?'#ff5f73':a.direction==='BULLISH'?'#28e0a1':'#ffd166';x.lineWidth=Math.max(3,w/350);x.setLineDash([10,7]);x.beginPath();p.forEach((q,i)=>i?x.lineTo(q.x*w,q.y*h):x.moveTo(q.x*w,q.y*h));x.stroke();x.setLineDash([])}r(c.toDataURL('image/png'))})}
async function render(d){const a=d.analysis||{},o=a.overall||{};document.getElementById('result').style.display='block';document.getElementById('count').textContent=d.count+' chart(s) analyzed';const dir=document.getElementById('dir');dir.textContent=(o.direction||'NEUTRAL')+' • '+(o.next_move||'WAIT');dir.className='direction '+(o.direction==='BULLISH'?'bull':o.direction==='BEARISH'?'bear':'neutral');document.getElementById('headline').textContent=o.headline||'Multi-timeframe analysis complete';document.getElementById('state').textContent=o.entry_plan||'';document.getElementById('risk').textContent=o.risk_note||'';document.getElementById('story').innerHTML=(o.market_story||[]).map(x=>'<li>'+esc(x)+'</li>').join('');document.getElementById('conf').innerHTML=(a.confluence||[]).map(x=>'<div class="step">'+esc(x)+'</div>').join('');document.getElementById('final').textContent=(a.final_diagram?.direction==='UP'?'🟢 CURRENT → ↑ ENTRY → ↑ TARGET':a.final_diagram?.direction==='DOWN'?'🔴 CURRENT → ↓ ENTRY → ↓ TARGET':'🟡 CURRENT → WAIT FOR CONFIRMATION')+'\n\n'+(a.final_diagram?.why||'');document.getElementById('plan').innerHTML='<b>'+esc(o.entry_plan||'Wait for confirmation')+'</b><br><br>Primary invalidation: '+esc(o.invalidation||'Not defined');document.getElementById('tutorial').innerHTML=(a.charts||[]).map((q,i)=>'<div class="step"><b>'+esc(q.timeframe||('Chart '+(i+1)))+'</b><br>'+esc(q.tutorial?.map(t=>t.title+': '+t.text).join(' • ')||q.current_state||'')+'</div>').join('');const box=document.getElementById('charts');box.innerHTML='';const inputs=[...document.querySelectorAll('.file')],tfs=[...document.querySelectorAll('.tf')];for(let i=0;i<inputs.length;i++)if(inputs[i].files[0]){const f=inputs[i].files[0],src=URL.createObjectURL(f),q=a.charts?.[i]||{};const card=document.createElement('div');card.className='chartCard';const h=document.createElement('div');h.className='chartHead';h.innerHTML='<b>'+esc(tfs[i].value)+'</b><span>'+esc(q.direction||'NEUTRAL')+' • '+esc(q.next_move||'WAIT')+'</span>';const img=document.createElement('img');img.src=await drawOverlay(src,q);img.onclick=()=>{big.src=img.src;modal.classList.add('open')};const inf=document.createElement('div');inf.className='chartInfo';const ob=q.valid_order_block||{};inf.innerHTML='<div class="ob"><b>ORDER BLOCK: '+esc(ob.status||'NONE')+'</b><br>'+esc(ob.why||'No reliable OB candidate.')+'<br><span class="small">Why not others: '+esc(ob.why_not_others||'Not enough evidence.')+'</span></div><div class="entry"><b>ENTRY / WATCH</b><br>'+esc(q.entry?.zone||'Not clearly visible')+'<br><span class="small">Trigger: '+esc(q.entry?.confirmation||'Confirmation required')+'<br>Invalidation: '+esc(q.entry?.invalidation||'Not defined')+'<br>Target: '+esc(q.entry?.target||'Not defined')+'</span></div>';card.append(h,img,inf);box.appendChild(card)}}
document.getElementById('go').disabled=false;window.scrollTo({top:document.getElementById('result').offsetTop-10,behavior:'smooth'})}
document.getElementById('close').onclick=()=>modal.classList.remove('open');modal.onclick=e=>{if(e.target===modal)modal.classList.remove('open')};document.getElementById('form').addEventListener('submit',async e=>{e.preventDefault();const err=document.getElementById('err'),btn=document.getElementById('go');err.textContent='';const inputs=[...document.querySelectorAll('.file')],tfs=[...document.querySelectorAll('.tf')],chosen=inputs.filter(x=>x.files[0]);if(!chosen.length){err.textContent='Upload at least one chart.';return}if(chosen.length>4){err.textContent='Maximum 4 charts.';return}btn.disabled=true;btn.textContent='ANALYZING ALL TIMEFRAMES…';const fd=new FormData();fd.append('symbol',document.querySelector('[name=symbol]').value);chosen.forEach((inp)=>{fd.append('charts[]',inp.files[0]);fd.append('timeframes[]',tfs[inputs.indexOf(inp)].value)});try{const r=await fetch('analyze.php',{method:'POST',body:fd}),d=await r.json();if(!r.ok||d.error)throw new Error(d.error||'Analysis failed');await render(d)}catch(x){err.textContent=x.message}finally{btn.disabled=false;btn.textContent='ANALYZE ALL TIMEFRAMES'}});
</script></body></html>
